const amqp = require('amqplib');

app.post('/api/video-upload', async (req, res) => {
  const videoData = req.body;

  // 1. Connect to RabbitMQ
  const connection = await amqp.connect('amqp://localhost');
  const channel = await connection.createChannel();

  // 2. Publish to queue for a background worker to compress
  channel.sendToQueue('video_compression', Buffer.from(JSON.stringify(videoData)));

  // 3. Immediately respond to client while background worker does the heavy lifting
  res.status(202).json({ message: 'Video upload processing started.' });
});
